import java.util.*;
/** A bounded, full block-resolution neighborhood of the current map. */
final class MinecraftMesh {
 record Batch(float[] vertices,boolean transparent){}
 record Patch(int x,int z,int side,List<Batch> batches,long faces){}
 static final class Floats{float[] a=new float[16384];int size;void add(float v){if(size==a.length)a=Arrays.copyOf(a,a.length*2);a[size++]=v;}float[] done(){return Arrays.copyOf(a,size);}}
 final int ox,oz,side,low,high,stride;final int[] voxels;final TerraForge.World world;final MinecraftAssets assets;
 MinecraftMesh(TerraForge.World w,MinecraftAssets a,int x,int z,int radius,TreeLibrary.SpatialIndex forest){world=w;assets=a;int span=Math.min(w.size,Math.max(16,radius*2));ox=Math.max(0,Math.min(w.size-span,(x-span/2)/16*16));oz=Math.max(0,Math.min(w.size-span,(z-span/2)/16*16));side=span;stride=side+2;int bottom=999,top=-64;for(int zz=Math.max(0,oz-1);zz<Math.min(w.size,oz+side+1);zz++)for(int xx=Math.max(0,ox-1);xx<Math.min(w.size,ox+side+1);xx++){bottom=Math.min(bottom,w.h(xx,zz)-4);top=Math.max(top,Math.max(w.h(xx,zz)+1,w.waterY(xx,zz)));}for(var placement:w.environment.trees){var tree=TreeLibrary.catalog().trees().get(placement.tree());int[] bounds=TreeLibrary.bounds(tree,placement.rotation());if(placement.x()+bounds[1]>=ox-1&&placement.x()+bounds[0]<=ox+side&&placement.z()+bounds[3]>=oz-1&&placement.z()+bounds[2]<=oz+side)top=Math.max(top,w.h(placement.x(),placement.z())+tree.height);}low=Math.max(-64,bottom);high=Math.min(w.buildHeight-65,top);voxels=new int[stride*stride*(high-low+1)];
  for(int zz=-1;zz<=side;zz++)for(int xx=-1;xx<=side;xx++){int wx=ox+xx,wz=oz+zz;if(wx<0||wz<0||wx>=w.size||wz>=w.size)continue;int h=w.h(wx,wz),mat=TerrainGenerator.surface(w,wx,wz),water=w.waterY(wx,wz),snow=w.snowLayers(wx,wz),ice=w.iceDepth(wx,wz),glacier=(int)Math.ceil(EnvironmentMap.at(w.environment.glacier,wz*w.size+wx,0)),soil=ExportBlocks.soilDepth(wx,wz,w.seed);for(int y=low;y<=Math.min(high,Math.max(h+1,water));y++)put(xx,y,zz,ExportBlocks.block(h,mat,water,snow,ice,glacier,y,soil));}
  if(!w.environment.trees.isEmpty())for(int cz=Math.max(0,oz-1)/16;cz<=Math.min(w.size-1,oz+side)/16;cz++)for(int cx=Math.max(0,ox-1)/16;cx<=Math.min(w.size-1,ox+side)/16;cx++){int[] overlay=forest.overlay(cx,cz);if(overlay==null)continue;for(int y=low;y<=high;y++)for(int zz=0;zz<16;zz++)for(int xx=0;xx<16;xx++){int id=overlay[(y+64)*256+zz*16+xx],x0=cx*16+xx-ox,z0=cz*16+zz-oz;if(id!=0&&x0>=-1&&x0<=side&&z0>=-1&&z0<=side)put(x0,y,z0,id);}}
 }
 void put(int x,int y,int z,int id){voxels[((y-low)*stride+z+1)*stride+x+1]=id;}
 int get(int x,int y,int z){return x< -1||z< -1||x>side||z>side||y<low||y>high?0:voxels[((y-low)*stride+z+1)*stride+x+1];}
 boolean translucent(int id){if(id==7||id==9)return true;return id>=22&&id<1000000&&ExportBlocks.state(id).name().contains("glass");}
 float[] tint(int id){String name=ExportBlocks.state(id).name();int color=name.contains("spruce")?0x619961:name.contains("birch")?0x80a755:0x91bd59;return new float[]{((color>>16)&255)/255f,((color>>8)&255)/255f,(color&255)/255f};}
 Patch build()throws Exception{List<Batch> batches=new ArrayList<>();long faces=0;Map<Integer,MinecraftAssets.Model> cache=new HashMap<>();Map<Integer,float[]> colors=new HashMap<>();for(int cz=0;cz<side;cz+=16)for(int cx=0;cx<side;cx+=16){if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException();Floats opaque=new Floats(),glass=new Floats();for(int z=cz;z<Math.min(cz+16,side);z++)for(int x=cx;x<Math.min(cx+16,side);x++)for(int y=low;y<=high;y++){int id=get(x,y,z);if(id==0)continue;var model=cache.get(id);if(model==null){model=assets.block(id);cache.put(id,model);}boolean transparent=translucent(id);float[] tint=colors.computeIfAbsent(id,this::tint);for(var face:model.faces()){int cull=face.cull();if(cull>=0){int[] delta=MinecraftAssets.NORMALS[cull];int other=get(x+delta[0],y+delta[1],z+delta[2]);if(other!=0){var neighbor=cache.get(other);if(neighbor==null){neighbor=assets.block(other);cache.put(other,neighbor);}if(neighbor.opaque()||(id==other&&(transparent||ExportBlocks.state(id).name().contains("leaves"))))continue;}}
   Floats out=transparent?glass:opaque;float shade=switch(face.direction()){case 0->.5f;case 1->1;case 2,3->.8f;default->.6f;};float alpha=id==7?.66f:transparent?.78f:1;
   float[] points=face.points();boolean waterFull=id==7&&get(x,y+1,z)==7;for(int vertex:new int[]{0,1,2,0,2,3}){out.add(ox+x+points[vertex*3]);out.add(y+(waterFull?points[vertex*3+1]/.8888889f:points[vertex*3+1]));out.add(oz+z+points[vertex*3+2]);out.add(face.uv()[vertex*2]);out.add(face.uv()[vertex*2+1]);out.add(face.tile());for(int c=0;c<3;c++){float value=face.tint()>0?tint[c]:1;if(id==7)value=new float[]{.247f,.463f,.894f}[c];out.add(value*shade);}out.add(alpha);}faces++;
  }}if(opaque.size>0)batches.add(new Batch(opaque.done(),false));if(glass.size>0)batches.add(new Batch(glass.done(),true));}
  return new Patch(ox,oz,side,List.copyOf(batches),faces);
 }
}
